import "server-only";
import QRCode from "qrcode";
import { getOrigin } from "@/lib/site-url";
import { CopyLink } from "./copy-link";

// For recruiting in person at the happy hour: a QR code that opens this team's page on
// someone else's phone. Shown to the team's members. The code is drawn dark on white in
// every theme so phone cameras read it.
export async function SharePanel({ teamId, teamName }: { teamId: string; teamName: string }) {
  const url = `${await getOrigin()}/teams/${teamId}`;
  // SVG markup generated by the qrcode library from our own URL, not from user input.
  const svg = await QRCode.toString(url, {
    type: "svg",
    margin: 2,
    errorCorrectionLevel: "M",
    color: { dark: "#141413", light: "#ffffff" },
  });

  return (
    <details className="group rounded-lg border border-line px-4 py-3">
      <summary className="cursor-pointer list-none text-sm font-medium">
        <span className="underline">Share {teamName}</span>{" "}
        <span className="text-fg-muted">: show a QR code so people can open your team on their phone</span>
      </summary>
      <div className="mt-4 flex flex-col items-center gap-3">
        <div
          className="w-full max-w-64 rounded-lg bg-white p-2"
          role="img"
          aria-label={`QR code for ${teamName}'s page`}
          dangerouslySetInnerHTML={{ __html: svg }}
        />
        <p className="break-all text-center text-sm text-fg-muted">{url}</p>
        <CopyLink url={url} />
      </div>
    </details>
  );
}
